import {esc} from './core.js';
export function cloudPanel(session=null,status='로그인하면 다른 기기와 여행 사본을 주고받을 수 있어요.'){
 const signedIn=!!session?.email;
 return '<section class="panel cloud-panel" id="cloud-panel"><h2>여행 클라우드</h2><p id="cloud-status" role="status">'+esc(status)+'</p>'+(signedIn?'<p class="note">'+esc(session.email)+'</p><div class="cloud-actions"><button class="primary" data-action="cloud-upload">클라우드에 저장</button><button class="secondary" data-action="cloud-import">클라우드에서 불러오기</button></div><details><summary>사본 확인·로그아웃</summary><div class="cloud-actions"><button class="secondary" data-action="cloud-inspect">클라우드 사본 확인</button><button class="secondary" data-action="cloud-logout">로그아웃</button></div><p class="note">먼저 사본을 확인한 뒤 저장하세요. 불러오기는 같은 ID의 여행을 덮어쓰지 않습니다. 사진은 전송하지 않으며 자동 동기화하지 않습니다.</p><details><summary>클라우드 사본 삭제</summary><button class="linkbtn full" data-action="cloud-delete">클라우드 여행 사본 삭제</button><p class="note">로컬 여행과 딱모둠 계정은 보존합니다.</p></details></details>':'<button class="primary full" data-action="cloud-google">로그인</button><details><summary>이메일 계정으로 로그인</summary><label for="cloud-email">딱모둠 계정 이메일</label><input id="cloud-email" type="email" autocomplete="username"><label for="cloud-password">비밀번호</label><input id="cloud-password" type="password" autocomplete="current-password"><button class="secondary full" data-action="cloud-login">이메일·비밀번호 로그인</button></details>')+'</section>';
}
